/// <summary>
/// ATL query over MD31 input rows (SJPMDItemMaster), on the pattern of AtlQueryProductItems.
/// Use with TEST_AtlSpecMD31ItemMasterRow and assertExpectedLinesSet.
/// </summary>
public final class TEST_AtlQueryMD31ItemMasterRows extends AtlQuery
{
}

Method.Source:
public static TEST_AtlQueryMD31ItemMasterRows construct()
{
    return new TEST_AtlQueryMD31ItemMasterRows();
}

public TEST_AtlQueryMD31ItemMasterRows forFileName(Filename _fileName)
{
    this.addQueryRange(fieldNum(SJPMDItemMaster, file_name), _fileName);

    return this;
}

public TEST_AtlQueryMD31ItemMasterRows withSkuCode(SJPMDItemMasterJANCode _skuCode)
{
    this.addQueryRange(fieldNum(SJPMDItemMaster, sku_cd), _skuCode);

    return this;
}
